import ipaddress as ipa

# Grupos de seguridad de juguete: solo reglas de ENTRADA que permiten
# (protocolo, puerto, origen). Lo que no casa con ninguna, se deniega.
GRUPOS = {
    "web": [("tcp", 443, "0.0.0.0/0")],        # HTTPS desde Internet
    "bd":  [("tcp", 5432, "10.0.1.0/24")],     # solo desde la web
}
IP_PUBLICA = {"web": True, "bd": False}
VPC = ipa.ip_network("10.0.0.0/16")

def entra(origen, servidor, proto, puerto):
    ip = ipa.ip_address(origen)
    if ip not in VPC and not IP_PUBLICA[servidor]:
        return "NO: sin IP pública, Internet no llega"
    for p, pto, red in GRUPOS[servidor]:
        if (p, pto) == (proto, puerto) and ip in ipa.ip_network(red):
            return f"SÍ: regla {p}/{pto} desde {red}"
    return "NO: ninguna regla lo permite"

pruebas = [("203.0.113.7", "web", "tcp", 443),
           ("203.0.113.7", "web", "tcp", 22),
           ("10.0.1.20", "bd", "tcp", 5432),
           ("10.0.3.4", "bd", "tcp", 5432),
           ("203.0.113.7", "bd", "tcp", 5432)]
for o, s, pr, pt in pruebas:
    print(f"{o:>11} -> {s + ":" + str(pt):<8} {entra(o, s, pr, pt)}")

# Un ARN tiene 6 campos separados por «:». El último (el recurso)
# puede llevar «/» o incluso «:», así que solo se corta 5 veces.
CAMPOS = ["arn", "partición", "servicio", "región", "cuenta", "recurso"]

def trocear(arn):
    partes = arn.split(":", 5)
    if len(partes) != 6 or partes[0] != "arn":
        raise ValueError(f"no es un ARN válido: {arn}")
    return dict(zip(CAMPOS, partes))

ejemplos = [
    "arn:aws:ec2:eu-west-1:123456789012:instance/i-0abc1234",
    "arn:aws:iam::123456789012:user/ana",
    "arn:aws:s3:::mi-bucket/fotos/logo.png",
]
print("serv región     cuenta       recurso")
for arn in ejemplos:
    d = trocear(arn)
    vacio = "-"  # campo vacío
    print(f"{d['servicio']:<4} {d['región'] or vacio:<10}",
          f"{d['cuenta'] or vacio:<12} {d['recurso']}")
try:
    trocear("i-0abc1234")   # el ID a secas no es un ARN
except ValueError as e:
    print("Error:", e)

